package com.example.demo;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;
@Entity @Getter @NoArgsConstructor public class Meeting {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private String title;private String category;@Column(length=300) private String description;private String placeName;private Double latitude;private Double longitude;private String startsAt;private int maxMembers;private boolean confirmed;@Column(length=1000) private String announcement;@ElementCollection @CollectionTable(name="meeting_images",joinColumns=@JoinColumn(name="meeting_id")) @Column(name="image_url",length=500) @OrderColumn(name="display_order") private List<String> imageUrls=new ArrayList<>();@Column(updatable=false) private LocalDateTime createdAt;@ManyToOne(fetch=FetchType.LAZY) private Member host;public Meeting(String title,String category,String description,String placeName,Double latitude,Double longitude,String startsAt,int maxMembers,Member host){this.title=title;this.category=category;this.description=description;this.placeName=placeName;this.latitude=latitude;this.longitude=longitude;this.startsAt=startsAt;this.maxMembers=maxMembers;this.host=host;}public void setImageUrls(List<String> imageUrls){this.imageUrls=imageUrls==null?new ArrayList<>():new ArrayList<>(imageUrls);}public void confirm(String announcement){this.announcement=announcement;this.confirmed=true;}@PrePersist private void setCreatedAt(){if(createdAt==null)createdAt=LocalDateTime.now();}}